package android.util; import java.io.*; import java.nio.file.*; public class AtomicFile {public static boolean failNext; final File base; public AtomicFile(File f){base=f;} public File getBaseFile(){return base;} public FileInputStream openRead()throws IOException{return new FileInputStream(base);} public FileOutputStream startWrite()throws IOException{if(failNext){failNext=false;throw new IOException("Injected disk error");}return new FileOutputStream(base+".new");} public void finishWrite(FileOutputStream o)throws IOException{o.getFD().sync();o.close();Files.move(new File(base+".new").toPath(),base.toPath(),StandardCopyOption.REPLACE_EXISTING);} public void failWrite(FileOutputStream o){try{o.close();}catch(Exception e){}}}